const text = $json.output ?? "";

const start = text.indexOf("{");
const end = text.lastIndexOf("}");

const instance = $('Edit Fields').first().json.Instance;
const from = $('Edit Fields').first().json.From;

if (start === -1 || end === -1 || end <= start) {
  return {
    hasAction: false,
    message: text,
    Instance: instance,
    From: from
  };
}

const possibleJson = text.substring(start, end + 1);

let parsed;

try {
  parsed = JSON.parse(possibleJson);
} catch (err) {
  return {
    hasAction: false,
    message: text,
    Instance: instance,
    From: from
  };
}

if (!parsed.agent_action) {
  return {
    hasAction: false,
    message: text.replace(possibleJson, "").trim(),
    Instance: instance,
    From: from
  };
}

return {
  hasAction: true,
  message: text.replace(possibleJson, "").trim(),
  action: parsed.agent_action.action,
  domain: parsed.agent_action.domain,
  detail: parsed.agent_action.detail,
  Instance: instance,
  From: from
};

const data = $json;

const pendentesHoje = data.pendentes_hoje ?? 0;
const pendentes24h = data.pendentes_24h ?? 0;
const pendentes7d = data.pendentes_7d ?? 0;
const pendentesTotal = data.pendentes_total ?? 0;

let message = `📊 *RESUMO OPERACIONAL – HOJE*\n\n`;

message += `🕒 *Pendências:*\n`;
message += `• Hoje: ${pendentesHoje}\n`;
message += `• +24h sem resposta: ${pendentes24h}\n`;
message += `• +7 dias sem resposta: ${pendentes7d}\n`;
message += `• Total de Pendencias: ${pendentesTotal}\n`;

if (data.acao_mais_antiga) {
  const date = new Date(data.acao_mais_antiga_data);
  const formattedDate = date.toLocaleString("pt-BR");

  message += `\n📌 *Ação mais antiga pendente:*\n`;
  message += `• ${data.acao_mais_antiga}\n`;
  message += `• Desde: ${formattedDate}\n`;
}

return {
  message
};

